"use strict";

/**
 * World Spec Applicator Module
 *
 * Takes a World Specification JSON (generated by AI or imported) and builds a
 * Fantasy Map Generator map whose geography, settlements and polities match
 * the spec as exactly as the cell grid allows.
 *
 * Pipeline (spec-only mode):
 *  1. Terrain   - paint heights deterministically from `terrain.features`
 *                 (see terrain-painter.js). Legacy `heightmapCommands` are
 *                 converted to features unless `terrain.useLegacyDsl` is set.
 *  2. Grid      - FMG's terrain-only generate(): features, rivers, biomes.
 *  3. Fidelity  - compare painted heights with what the spec asked for.
 *  4. Cultures  - spec cultures only, balanced multi-source expansion.
 *  5. States    - spec states with capitals on their exact locations.
 *  6. Burgs     - settlement locations become burgs at their exact cells;
 *                 landmarks/natural features become markers with notes.
 *  7. Expansion - FMG state expansion, statistics, label poles.
 *  8. Religions, zones, emblems, redraw.
 *
 * Placement never "optimizes" a location away from where the spec put it: a
 * location goes on the nearest valid cell and the displacement is recorded in
 * the result so callers (UI, tests) can see exactly how faithful the map is.
 */

import FlatQueue from "flatqueue";
import {findCell, findAll} from "../../utils/graphUtils.js";
import {getRandomColor} from "../../utils/colorUtils.js";
import {analyzeWorldSpec, getConflictSummary, hasTerritorialWarfare} from "./world-spec-validator.js";
import {paintTerrain, featuresFromHeightmapCommands, SEA_LEVEL} from "./terrain-painter.js";
import {checkSpecFidelity, checkBorderFidelity} from "./terrain-fidelity.js";
import {
  resolveLatitudeBand,
  latitudeBandToMapOptions,
  buildDiplomacy,
  mapNameFromSpec,
  resolveWinds,
  longitudeToOption
} from "./spec-options.js";

const STYLE_PRESETS = ["default", "ancient", "gloom", "pale", "watercolor", "clean", "atlas", "cyberpunk", "night", "monochrome"];
const BURG_TYPES = ["Generic", "Naval", "Lake", "Highland", "River", "Nomadic", "Hunting"];

const CUSTOM_HEIGHTMAP_ID = "world-spec-features";
const LEGACY_HEIGHTMAP_ID = "world-spec-custom";

// Error tracking for UI display
let applicatorErrors = [];
let applicatorWarnings = [];

// Store for spec data during generation
let _specData = null;

function logApplicatorError(stage, error, context = {}) {
  const errorEntry = {stage, error: error.message || String(error), context, timestamp: Date.now()};
  applicatorErrors.push(errorEntry);
  console.error(`[WorldSpecApplicator] ${stage} failed:`, error, context);
  return errorEntry;
}

function logWarning(stage, message, context = {}) {
  applicatorWarnings.push({stage, message, context});
  console.warn(`[WorldSpecApplicator] ${stage}: ${message}`);
}

function clearErrors() {
  applicatorErrors = [];
  applicatorWarnings = [];
}

function getErrors() {
  return [...applicatorErrors];
}

function getWarnings() {
  return [...applicatorWarnings];
}

