export function isSettlementLocation(loc) {
  const kind = String(loc.kind || "").toLowerCase();
  if (kind === "settlement") return true;
  if (kind === "landmark" || kind === "natural" || kind === "site") return false;

  const type = String(loc.type || "").toLowerCase().trim();
  if (SETTLEMENT_TYPES.has(type)) return true;
  if (MARKER_STYLES[type]) return false;

  // Compound types like "fishing village" or "mountain fortress"
  for (const settlement of SETTLEMENT_TYPES) {
    if (type.endsWith(settlement)) return true;
  }
  for (const marker of Object.keys(MARKER_STYLES)) {
    if (type.endsWith(marker)) return false;
  }
  return true; // unknown types default to a settlement, matching legacy behaviour
}

function markerStyleFor(loc) {
  const type = String(loc.type || "").toLowerCase().trim();
  if (MARKER_STYLES[type]) return MARKER_STYLES[type];
  for (const key of Object.keys(MARKER_STYLES)) {
    if (type.includes(key)) return MARKER_STYLES[key];
  }
  return MARKER_STYLES.landmark;
}

function wantsCoast(loc) {
  const terrain = String(loc.terrain || "").toLowerCase();
  if (terrain === "coast") return true;
  const type = String(loc.type || "").toLowerCase();
  return type.includes("port") || type.includes("harbor") || type.includes("harbour") || type.includes("lighthouse") || type.includes("shipyard");
}

function defaultPopulation(loc) {
  if (loc.population) return loc.population;
  const type = String(loc.type || "").toLowerCase();
  if (type.includes("metropolis")) return 20;
  if (type.includes("city") || type.includes("capital")) return 10;
  if (type.includes("town") || type.includes("port")) return 4;
  if (type.includes("fortress") || type.includes("castle") || type.includes("citadel") || type.includes("stronghold")) return 2;
  if (type.includes("village") || type.includes("monastery")) return 1.2;
  if (type.includes("camp") || type.includes("outpost") || type.includes("tower") || type.includes("hamlet")) return 0.5;
  return 1.5;
}

// ============================================================================
// Coordinate utilities
// ============================================================================

function normalizedToMapCoords(normX, normY) {
  return {x: normX * graphWidth, y: normY * graphHeight};
}

function findNearestCell(normX, normY) {
  const {x, y} = normalizedToMapCoords(normX, normY);
  return findCell(x, y);
}

function cellSpacing() {
  if (typeof window !== "undefined" && window.grid?.spacing) return window.grid.spacing;
  return Math.sqrt((graphWidth * graphHeight) / Math.max(1, pack.cells.i.length));
}

function isLand(cell) {
  return pack.cells.h[cell] >= SEA_LEVEL;
}

function isCoastal(cell) {
  if (pack.cells.haven?.[cell]) return true;
  if (pack.cells.t?.[cell] === 1) return true;
  return (pack.cells.c[cell] || []).some(n => pack.cells.h[n] < SEA_LEVEL);
}

/**
 * Place something as close as possible to normalized coordinates.
 *
 * Searches outward ring by ring and returns the *nearest* cell satisfying the
 * constraints, never the "best" one. Returns {cell, displacement, exact}
 * where displacement is in map pixels, or cell = null if nothing qualifies
 * within maxRadius.
 */
function placeNear(normX, normY, {requireLand = true, requireCoast = false, requireFree = true, maxRadiusFraction = 0.12} = {}) {
  const {x, y} = normalizedToMapCoords(normX, normY);
  const cells = pack.cells;
  const spacing = cellSpacing();
  const maxRadius = Math.min(graphWidth, graphHeight) * maxRadiusFraction;

  const qualifies = c => {
    if (c === undefined || c === null) return false;
    if (requireLand && !isLand(c)) return false;
    if (requireFree && cells.burg[c]) return false;
    if (requireCoast && !isCoastal(c)) return false;
    return true;
  };

  const exact = findCell(x, y);
  if (qualifies(exact)) {
    const [cx, cy] = cells.p[exact];
    return {cell: exact, displacement: Math.hypot(cx - x, cy - y), exact: true};
  }

  let radius = spacing * 1.5;
  let best = null;
  while (radius <= maxRadius + spacing) {
    const candidates = findAll(x, y, radius).filter(qualifies);
    for (const c of candidates) {
      const [cx, cy] = cells.p[c];
      const d = Math.hypot(cx - x, cy - y);
      if (!best || d < best.displacement) best = {cell: c, displacement: d, exact: false};
    }
    if (best) return best;
    radius *= 1.6;
  }

  return {cell: null, displacement: Infinity, exact: false};
}

/**
 * Place a settlement: exact cell if valid, else nearest valid cell nearby,
 * else (loudly) the nearest land anywhere so the location is never lost.
 */
function placeSettlement(loc) {
  const coast = wantsCoast(loc);
  let placed = placeNear(loc.x, loc.y, {requireLand: true, requireFree: true, requireCoast: coast});
  if (placed.cell === null && coast) {
    placed = placeNear(loc.x, loc.y, {requireLand: true, requireFree: true});
    if (placed.cell !== null) logWarning("placement", `No coast near "${loc.name}", placed inland`);
  }
  if (placed.cell === null) {
    placed = placeNear(loc.x, loc.y, {requireLand: true, requireFree: true, maxRadiusFraction: 0.6});
    if (placed.cell !== null) {
      placed.farFallback = true;
      logWarning("placement", `"${loc.name}" is on water in the spec terrain; moved to the nearest land far away`, {
        displacementPx: Math.round(placed.displacement)
      });
    }
  }
  return placed;
}

/** Nearest land cell with generous radius (used for culture/religion centers). */
function findNearestLandCell(normX, normY) {
  const placed = placeNear(normX, normY, {requireLand: true, requireFree: false, maxRadiusFraction: 0.25});
  if (placed.cell === null) {
    console.warn(`[WorldSpecApplicator] No land cell found near (${normX}, ${normY})`);
    return null;
  }
  return placed.cell;
}

/** Backward compatible wrapper returning just the cell id. */
function findSuitableBurgCell(normX, normY, options = {}) {
  const placed = placeNear(normX, normY, {
    requireLand: true,
    requireFree: true,
    requireCoast: !!options.preferCoastal
  });
  if (placed.cell !== null) return placed.cell;
  if (options.preferCoastal) {
    const relaxed = placeNear(normX, normY, {requireLand: true, requireFree: true});
    if (relaxed.cell !== null) return relaxed.cell;
  }
  return findNearestLandCell(normX, normY);
}

// ============================================================================
// Validation
// ============================================================================

function validateSpec(spec) {
  const errors = [];
  const warnings = [];

  if (!spec.terrain) errors.push("Missing 'terrain' property");
  if (!spec.locations) errors.push("Missing 'locations' property");
  if (!spec.states) errors.push("Missing 'states' property");

  if (spec.terrain) {
    const hasFeatures = Array.isArray(spec.terrain.features) && spec.terrain.features.length > 0;
    const hasCommands = Array.isArray(spec.terrain.heightmapCommands) && spec.terrain.heightmapCommands.length > 0;
    if (!hasFeatures && !hasCommands) {
      warnings.push("No terrain features or heightmap commands, terrain will be default");
    }
    if (!hasFeatures && hasCommands) {
      warnings.push("Spec uses legacy heightmap commands; they will be converted to deterministic terrain features");
    }
    if (!spec.terrain.template && !hasFeatures) warnings.push("No terrain template specified, using 'continents'");
  }

  const locationIds = new Set((spec.locations || []).map(l => l.id));
  const stateIds = new Set((spec.states || []).map(s => s.id));

  for (const state of spec.states || []) {
    if (state.capital && !locationIds.has(state.capital)) {
      warnings.push(`State '${state.name}' references missing capital '${state.capital}'`);
    }
  }
  for (const loc of spec.locations || []) {
    if (loc.owner && loc.owner !== "none" && !stateIds.has(loc.owner)) {
      warnings.push(`Location '${loc.name}' references missing owner '${loc.owner}'`);
    }
  }

  let conflictInfo = null;
  let territorialWarnings = [];
  try {
    const analysis = analyzeWorldSpec(spec);
    if (analysis.issues) errors.push(...analysis.issues.filter(i => !errors.includes(i)));
    if (analysis.warnings) warnings.push(...analysis.warnings.filter(w => !warnings.includes(w)));
    conflictInfo = getConflictSummary(spec);
    if (hasTerritorialWarfare(spec)) {
      territorialWarnings = analysis.warnings.filter(
        w => w.includes("territorialRole") || w.includes("front line") || w.includes("defender side") || w.includes("attacker side")
      );
    }
  } catch (e) {
    console.warn("[WorldSpecApplicator] Enhanced validation unavailable:", e.message);
  }

  return {valid: errors.length === 0, errors, warnings, conflictInfo, territorialWarnings};
}

