function resolveNameBase(baseName) {
  if (!baseName) return 0;
  const normalized = String(baseName).toLowerCase();
  const baseNameMap = {
    english: 1,
    celtic: 22,
    germanic: 0,
    german: 0,
    nordic: 6,
    norse: 6,
    greek: 7,
    roman: 8,
    latin: 8,
    slavic: 5,
    arabic: 18,
    japanese: 12,
    chinese: 11,
    korean: 10,
    spanish: 4,
    french: 2,
    italian: 3,
    portuguese: 13,
    turkish: 16,
    persian: 24,
    indian: 26,
    african: 28,
    fantasy: 32
  };
  return baseNameMap[normalized] ?? 0;
}

// ============================================================================
// Seed
// ============================================================================

/** Stable seed derived from the spec so the same spec always yields the same map. */
export function seedFromSpec(spec) {
  if (spec.seed) return String(spec.seed);
  const text = JSON.stringify({t: spec.terrain, l: spec.locations, s: spec.states});
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return String(hash);
}

// ============================================================================
// Main generation
// ============================================================================

async function generateFromSpec(spec) {
  clearErrors();
  _specData = spec;

  const validation = validateSpec(spec);
  if (!validation.valid) {
    for (const error of validation.errors) logApplicatorError("validation", new Error(error));
    _specData = null;
    throw new Error(`Invalid world spec: ${validation.errors.join(", ")}`);
  }
  for (const warning of validation.warnings) console.warn(`[WorldSpecApplicator] ${warning}`);

  if (validation.conflictInfo) {
    console.log(`[WorldSpecApplicator] Conflict: ${validation.conflictInfo.description}`);
  }
  for (const warning of validation.territorialWarnings || []) {
    console.warn(`[WorldSpecApplicator] territorial: ${warning}`);
  }

  const seed = seedFromSpec(spec);
  const templateState = rememberTemplateState();
  const placement = [];

  try {
    console.log("[WorldSpecApplicator] Step 1: Setting up terrain...");
    const terrainMode = setupHeightmapTemplate(spec.terrain, seed);

    console.log("[WorldSpecApplicator] Step 2: Generating terrain-only map...");
    applyClimateSettings(spec.terrain?.climateSettings);
    if (typeof window.undraw === "function") window.undraw(); // drop the previous map's labels, emblems, notes
    await generateTerrainOnlyMap(spec, seed);

    console.log("[WorldSpecApplicator] Step 3: Checking terrain fidelity...");
    const fidelity = checkFidelity(spec, terrainMode);

    console.log("[WorldSpecApplicator] Step 4: Creating spec cultures...");
    createSpecCultures(spec.cultures || [], spec);

    console.log("[WorldSpecApplicator] Step 5: Creating spec states...");
    createSpecStates(spec.states || [], spec.locations || [], placement);

    console.log("[WorldSpecApplicator] Step 6: Creating spec burgs and markers...");
    createSpecBurgs(spec.locations || [], placement);

    console.log("[WorldSpecApplicator] Step 7: Expanding state territories...");
    expandStateTerritories(placement);

    if (spec.religions && spec.religions.length > 0) {
      console.log("[WorldSpecApplicator] Step 8: Creating spec religions...");
      createSpecReligions(spec.religions);
    }

    console.log("[WorldSpecApplicator] Step 8b: Roads, burg features, diplomacy, provinces, military, markers, name...");
    generateRoutes();
    defineBurgFeatures();
    assignBurgTypes(spec.locations || []);
    applyDiplomacy(spec);
    generateProvinces(spec);
    if (spec.options?.military !== false) generateMilitary();
    if (spec.options?.flavourMarkers !== false) generateFlavourMarkers();
    applyMapName(spec);
    if (fidelity) fidelity.borders = checkBorders(spec);

    if (spec.zones && spec.zones.length > 0) {
      console.log("[WorldSpecApplicator] Step 9: Applying zones...");
      applyZones(spec.zones);
    }

    console.log("[WorldSpecApplicator] Step 10: Ensuring COAs exist...");
    ensureCoasExist();

    console.log("[WorldSpecApplicator] Step 11: Redrawing layers...");
    redrawMapLayers();
    await applyStylePreset(spec.map?.style);

    const placementSummary = summarizePlacement(placement);
    console.log("[WorldSpecApplicator] Generation complete!", placementSummary);
    if (fidelity?.summary) console.log("[WorldSpecApplicator] Fidelity:\n  " + fidelity.summary.join("\n  "));

    return {
      success: true,
      seed,
      terrainMode,
      errors: getErrors(),
      warnings: getWarnings(),
      fidelity,
      placement,
      placementSummary,
      stats: {
        cultures: pack.cultures.length - 1,
        states: pack.states.length - 1,
        burgs: pack.burgs.length - 1,
        markers: pack.markers.length,
        specMarkers: pack.markers.filter(m => m.specId).length,
        flavourMarkers: pack.markers.filter(m => !m.specId).length,
        provinces: Math.max(0, (pack.provinces?.length || 1) - 1),
        regiments: (pack.states || []).reduce((n, s) => n + (s.military?.length || 0), 0),
        routes: pack.routes?.length || 0,
        religions: pack.religions.length - 1
      }
    };
  } catch (error) {
    logApplicatorError("generation", error);
    throw error;
  } finally {
    _specData = null;
    restoreTemplateState(templateState);
  }
}

// ----------------------------------------------------------------------------
// Terrain
// ----------------------------------------------------------------------------

/**
 * Prepare the heightmap source for generate():
 *  - features (or converted legacy commands) → deterministic painter
 *  - legacy DSL (opt-in via terrain.useLegacyDsl) → custom template string
 *  - nothing → the named base template
 * Returns the mode used.
 */
function setupHeightmapTemplate(terrain, seed) {
  const templateInput = document.getElementById("templateInput");
  const templates = window.heightmapTemplates;
  const HG = window.HeightmapGenerator;

  if (!terrain) {
    console.warn("[WorldSpecApplicator] No terrain config provided");
    return "default";
  }

  let features = Array.isArray(terrain.features) ? terrain.features : [];
  const commands = Array.isArray(terrain.heightmapCommands) ? terrain.heightmapCommands : [];
  let mode = "features";

  if (features.length === 0 && commands.length > 0) {
    if (terrain.useLegacyDsl) {
      mode = "legacy-dsl";
    } else {
      features = featuresFromHeightmapCommands(commands);
      mode = features.length > 0 ? "converted-dsl" : "template";
      console.log(`[WorldSpecApplicator] Converted ${commands.length} legacy commands into ${features.length} terrain features`);
    }
  } else if (features.length === 0) {
    mode = "template";
  }

  if (mode === "features" || mode === "converted-dsl") {
    if (!HG?.registerCustom) throw new Error("HeightmapGenerator.registerCustom not available");
    const terrainForPainter = {...terrain, features};
    HG.registerCustom(CUSTOM_HEIGHTMAP_ID, graph =>
      paintTerrain(terrainForPainter, graph, {width: graphWidth, height: graphHeight, seed})
    );
    selectTemplateOption(templateInput, CUSTOM_HEIGHTMAP_ID, "World Spec Terrain");
    console.log(`[WorldSpecApplicator] Registered deterministic terrain with ${features.length} features`);
  } else if (mode === "legacy-dsl") {
    if (!templates) throw new Error("window.heightmapTemplates not available");
    templates[LEGACY_HEIGHTMAP_ID] = {name: "World Spec Custom", template: commands.join("\n")};
    selectTemplateOption(templateInput, LEGACY_HEIGHTMAP_ID, "World Spec Custom");
    console.log("[WorldSpecApplicator] Using legacy heightmap DSL:", commands.join("; "));
  } else {
    const template = terrain.template && templates?.[terrain.template] ? terrain.template : "continents";
    selectTemplateOption(templateInput, template, templates?.[template]?.name || template);
    console.log("[WorldSpecApplicator] Using base template:", template);
  }

  // Lock so generate() does not randomize the template away
  if (typeof window.lock === "function") window.lock("template");
  return mode;
}

function selectTemplateOption(select, value, label) {
  if (!select) return;
  let option = select.querySelector(`option[value="${value}"]`);
  if (!option) {
    option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    select.appendChild(option);
  }
  select.value = value;
}

const GLOBE_OPTIONS = ["mapSize", "latitude", "longitude"];

function rememberTemplateState() {
  const select = document.getElementById("templateInput");
  const lockEl = document.getElementById("lock_template");
  const globe = {};
  for (const key of GLOBE_OPTIONS) {
    globe[key] = {
      locked: document.getElementById("lock_" + key)?.dataset.locked === "1",
      stored: typeof localStorage !== "undefined" ? localStorage.getItem(key) : null
    };
  }
  return {
    value: select?.value,
    locked: lockEl?.dataset.locked === "1",
    stored: typeof localStorage !== "undefined" ? localStorage.getItem("template") : null,
    globe
  };
}

/**
 * Put the template option back the way it was so the custom id is never
 * persisted to localStorage (which would break the next page load).
 */
function restoreTemplateState(state) {
  try {
    const select = document.getElementById("templateInput");
    const HG = window.HeightmapGenerator;
    const templates = window.heightmapTemplates;
    if (select && state.value && state.value !== CUSTOM_HEIGHTMAP_ID && state.value !== LEGACY_HEIGHTMAP_ID) {
      select.value = state.value;
    } else if (select) {
      select.value = "continents";
    }
    if (typeof window.unlock === "function") window.unlock("template");
    if (state.locked && state.stored && state.stored !== CUSTOM_HEIGHTMAP_ID && state.stored !== LEGACY_HEIGHTMAP_ID) {
      localStorage.setItem("template", state.stored);
      if (typeof window.lock === "function") window.lock("template");
    }
    if (templates) delete templates[LEGACY_HEIGHTMAP_ID];
    HG?.unregisterCustom?.(CUSTOM_HEIGHTMAP_ID);
    // globe position: we locked these so generate() would not randomize them; put the locks back
    for (const key of GLOBE_OPTIONS) {
      const prev = state.globe?.[key];
      if (!prev) continue;
      if (typeof window.unlock === "function") window.unlock(key);
      if (prev.locked && prev.stored !== null) {
        localStorage.setItem(key, prev.stored);
        if (typeof window.lock === "function") window.lock(key);
      }
    }
    const stale = select?.querySelectorAll(`option[value="${CUSTOM_HEIGHTMAP_ID}"], option[value="${LEGACY_HEIGHTMAP_ID}"]`);
    stale?.forEach(o => o.remove());
  } catch (error) {
    console.warn("[WorldSpecApplicator] Could not restore template state:", error);
  }
}

/** Push the spec's climate into FMG's options so temperatures/biomes follow the story. */
function applyClimateSettings(climate) {
  climate = climate || {};
  try {
    const setInput = (id, value) => {
      const el = document.getElementById(id);
      if (el && value !== undefined && value !== null && !Number.isNaN(+value)) el.value = value;
    };
    if (typeof climate.temperatureEquator === "number") {
      setInput("temperatureEquatorInput", climate.temperatureEquator);
      setInput("temperatureEquatorOutput", climate.temperatureEquator);
      if (window.options) window.options.temperatureEquator = climate.temperatureEquator;
    }
    if (typeof climate.temperatureNorthPole === "number") {
      setInput("temperatureNorthPoleInput", climate.temperatureNorthPole);
      setInput("temperatureNorthPoleOutput", climate.temperatureNorthPole);
      if (window.options) window.options.temperatureNorthPole = climate.temperatureNorthPole;
    }
    if (typeof climate.temperatureSouthPole === "number") {
      setInput("temperatureSouthPoleInput", climate.temperatureSouthPole);
      setInput("temperatureSouthPoleOutput", climate.temperatureSouthPole);
      if (window.options) window.options.temperatureSouthPole = climate.temperatureSouthPole;
    } else if (typeof climate.temperatureNorthPole === "number" && window.options) {
      window.options.temperatureSouthPole = climate.temperatureNorthPole;
      setInput("temperatureSouthPoleInput", climate.temperatureNorthPole);
    }
    const precipitationMap = {arid: 30, dry: 60, low: 60, moderate: 100, medium: 100, high: 150, wet: 150, monsoon: 200};
    const prec = precipitationMap[String(climate.precipitation || "").toLowerCase()];
    if (prec) {
      setInput("precInput", prec);
      setInput("precOutput", prec);
    }

    // Globe position: where on the planet the map sits decides temperatures and biomes.
    // defineMapSize() randomizes these unless they are locked, so set and lock them.
    const band = resolveLatitudeBand(climate);
    const globe = latitudeBandToMapOptions(band);
    setInput("mapSizeInput", globe.mapSize);
    setInput("mapSizeOutput", globe.mapSize);
    setInput("latitudeInput", globe.latitude);
    setInput("latitudeOutput", globe.latitude);
    setInput("longitudeInput", globe.longitude);
    setInput("longitudeOutput", globe.longitude);
    if (typeof climate.longitude === "number") {
      const aspect = graphWidth / graphHeight;
      const lon = longitudeToOption(climate.longitude, band, aspect);
      setInput("longitudeInput", lon);
      setInput("longitudeOutput", lon);
    }
    if (typeof window.lock === "function") GLOBE_OPTIONS.forEach(key => window.lock(key));
    console.log(`[WorldSpecApplicator] Globe position from ${band.source}: ${band.south}° to ${band.north}° (mapSize ${globe.mapSize}%, latitude ${globe.latitude}%)`);

    // Prevailing winds (6 latitude tiers) drive where rain falls
    const winds = resolveWinds(climate);
    if (winds && window.options) {
      window.options.winds = winds;
      console.log(`[WorldSpecApplicator] Winds set to ${winds.join(",")}`);
    }
  } catch (error) {
    console.warn("[WorldSpecApplicator] Could not apply climate settings:", error);
  }
}

function generateTerrainOnlyMap(spec, seed) {
  return new Promise((resolve, reject) => {
    try {
      const mapSize = calculateMapSizeForSpec(spec);
      console.log("[WorldSpecApplicator] Map size for spec:", mapSize);

      const options = {
        specOnly: true,
        seed,
        mapWidth: mapSize.width,
        mapHeight: mapSize.height,
        cellCount: mapSize.cells
      };

      if (typeof window.generate !== "function") return reject(new Error("window.generate function not available"));

      window
        .generate(options)
        .then(() => {
          console.log("[WorldSpecApplicator] Terrain-only generation complete", {
            cells: pack.cells?.i?.length || 0,
            landCells: pack.cells?.h ? Array.from(pack.cells.h).filter(h => h >= SEA_LEVEL).length : 0
          });
          resolve();
        })
        .catch(reject);
    } catch (error) {
      reject(error);
    }
  });
}

function calculateMapSizeForSpec(spec) {
  if (spec.map?.width && spec.map?.height) {
    return {width: spec.map.width, height: spec.map.height, cells: spec.map.cells || 10000};
  }
  const locationCount = (spec.locations || []).length;
  if (locationCount <= 5) return {width: 800, height: 600, cells: 3000};
  if (locationCount <= 10) return {width: 1000, height: 750, cells: 5000};
  if (locationCount <= 20) return {width: 1200, height: 900, cells: 8000};
  return {width: 1600, height: 1000, cells: 10000};
}

function checkFidelity(spec, terrainMode) {
  try {
    const terrain = spec.terrain || {};
    const effectiveTerrain =
      terrainMode === "converted-dsl"
        ? {...terrain, features: featuresFromHeightmapCommands(terrain.heightmapCommands || [])}
        : terrain;
    const graph = typeof window !== "undefined" && window.grid?.cells?.h ? window.grid : null;
    const heights = graph ? graph.cells.h : pack.cells.h;
    const points = graph ? graph.points : pack.cells.p;
    const report = checkSpecFidelity({...spec, terrain: effectiveTerrain}, heights, points, {
      width: graphWidth,
      height: graphHeight
    });
    report.sampledFrom = graph ? "grid" : "pack";
    report.terrainMode = terrainMode;
    for (const f of report.terrain.features) {
      if (!f.passed) logWarning("fidelity", `terrain feature "${f.id}" (${f.type}) only ${Math.round(f.ratio * 100)}% ${f.expected}`);
    }
    for (const l of report.locations.locations) {
      if (!l.passed) logWarning("fidelity", `location "${l.name}" expected ${l.label} but terrain height there is ${l.height}`);
    }
    return report;
  } catch (error) {
    logApplicatorError("fidelity", error);
    return null;
  }
}

// ----------------------------------------------------------------------------
// Cultures
// ----------------------------------------------------------------------------

function createSpecCultures(specCultures, spec) {
  if (!specCultures || specCultures.length === 0) {
    console.log("[WorldSpecApplicator] No cultures in spec, using default");
    return;
  }

  console.log("[WorldSpecApplicator] Creating", specCultures.length, "cultures from spec");
  const locationById = new Map((spec.locations || []).map(l => [l.id, l]));

  for (let i = 0; i < specCultures.length; i++) {
    const specCulture = specCultures[i];
    const cultureIndex = i + 1; // Index 0 is Wildlands

    let centerCell = null;
    if (specCulture.x !== undefined && specCulture.y !== undefined) {
      centerCell = findNearestLandCell(specCulture.x, specCulture.y);
    }
    if (centerCell === null) {
      // Centre on the capital of the first state of this culture, or on the
      // centroid of the locations owned by states of this culture
      const anchor = cultureAnchor(specCulture, spec, locationById);
      if (anchor) centerCell = findNearestLandCell(anchor.x, anchor.y);
    }
    if (centerCell === null) centerCell = firstLandCell();

    let shield = "heater";
    if (typeof window.Cultures?.getRandomShield === "function") shield = window.Cultures.getRandomShield();

    const culture = {
      i: cultureIndex,
      name: specCulture.name || `Culture ${cultureIndex}`,
      type: specCulture.type || "Generic",
      base: resolveNameBase(specCulture.base),
      center: centerCell,
      color: specCulture.color || getRandomColor(),
      expansionism: specCulture.expansionism || 1,
      shield,
      removed: false
    };
    pack.cultures.push(culture);
    console.log(`[WorldSpecApplicator] Created culture ${cultureIndex}: ${culture.name} at cell ${centerCell}`);
  }

  expandCulturesToFillLand();
}

function cultureAnchor(specCulture, spec, locationById) {
  const matches = s =>
    s.culture && (s.culture === specCulture.id || String(s.culture).toLowerCase() === String(specCulture.name).toLowerCase());
  const states = (spec.states || []).filter(matches);
  for (const state of states) {
    const capital = locationById.get(state.capital);
    if (capital) return capital;
  }
  const owned = (spec.locations || []).filter(l => states.some(s => s.id === l.owner));
  if (owned.length) {
    return {
      x: owned.reduce((a, l) => a + l.x, 0) / owned.length,
      y: owned.reduce((a, l) => a + l.y, 0) / owned.length
    };
  }
  return null;
}

function firstLandCell() {
  for (let c = 0; c < pack.cells.i.length; c++) if (isLand(c)) return c;
  return null;
}

/**
 * Multi-source breadth-first expansion: every culture grows one ring per
 * round from its centre, so territories are balanced Voronoi-like regions
 * rather than whichever culture happened to be scanned first.
 */
function expandCulturesToFillLand() {
  const cells = pack.cells;
  const n = cells.i.length;
  cells.culture = new Uint16Array(n);

  let frontier = [];
  for (let i = 1; i < pack.cultures.length; i++) {
    const c = pack.cultures[i];
    if (c.removed || c.center === null || c.center === undefined) continue;
    cells.culture[c.center] = i;
    frontier.push(c.center);
  }
  if (!frontier.length) return;

  // Dijkstra from every centre; a culture's expansionism shrinks its step cost
  const cost = new Float64Array(n).fill(Infinity);
  const queue = new FlatQueue();
  for (const cell of frontier) {
    cost[cell] = 0;
    queue.push(cell, 0);
  }
  let rounds = 0;
  while (queue.length) {
    const priority = queue.peekValue();
    const cell = queue.pop();
    if (priority > cost[cell]) continue;
    rounds++;
    const id = cells.culture[cell];
    const expansionism = pack.cultures[id]?.expansionism || 1;
    const [cx, cy] = cells.p[cell];
    for (const nb of cells.c[cell] || []) {
      if (!isLand(nb)) continue;
      const [nx, ny] = cells.p[nb];
      const total = cost[cell] + Math.hypot(nx - cx, ny - cy) / expansionism;
      if (total < cost[nb]) {
        cost[nb] = total;
        cells.culture[nb] = id;
        queue.push(nb, total);
      }
    }
  }

  // Water cells take the culture of the nearest land neighbour (for coastlines/labels)
  for (let c = 0; c < n; c++) {
    if (isLand(c) || cells.culture[c]) continue;
    const nb = (cells.c[c] || []).find(x => cells.culture[x]);
    if (nb !== undefined) cells.culture[c] = cells.culture[nb];
  }

  console.log(`[WorldSpecApplicator] Culture expansion visited ${rounds} cells`);
}

// ----------------------------------------------------------------------------
// States and burgs
// ----------------------------------------------------------------------------

function buildCultureLookup() {
  const byName = new Map();
  for (let i = 1; i < pack.cultures.length; i++) byName.set(pack.cultures[i].name.toLowerCase(), i);
  const byId = new Map();
  (_specData?.cultures || []).forEach((c, idx) => c.id && byId.set(c.id, idx + 1));
  return ref => {
    if (!ref) return 0;
    return byId.get(ref) || byName.get(String(ref).toLowerCase()) || 0;
  };
}

function recordPlacement(placement, loc, placed, as, extra = {}) {
  const spacing = cellSpacing();
  const entry = {
    id: loc.id,
    name: loc.name,
    type: loc.type,
    as,
    cell: placed.cell,
    displacementPx: Math.round(placed.displacement),
    displacementCells: Math.round((placed.displacement / spacing) * 10) / 10,
    exact: placed.exact,
    farFallback: !!placed.farFallback,
    ...extra
  };
  placement.push(entry);
  if (entry.displacementCells > 2) {
    logWarning("placement", `"${loc.name}" moved ${entry.displacementCells} cells from its spec position`, entry);
  }
  return entry;
}

function createSpecStates(specStates, specLocations, placement) {
  console.log("[WorldSpecApplicator] Creating spec states:", specStates.length);

  const locationById = new Map(specLocations.map(l => [l.id, l]));
  const resolveCulture = buildCultureLookup();
  const stateIndexBySpecId = new Map();

  for (const specState of specStates) {
    // Capital: explicit, else first owned settlement flagged capital, else first owned settlement
    let capitalLoc = specState.capital ? locationById.get(specState.capital) : null;
    const ownedBy = l => ownerOf(l) === specState.id;
    if (!capitalLoc) capitalLoc = specLocations.find(l => ownedBy(l) && l.isCapital && isSettlementLocation(l));
    if (!capitalLoc) capitalLoc = specLocations.find(l => ownedBy(l) && isSettlementLocation(l));

    if (!capitalLoc) {
      logWarning("states", `State '${specState.name}' has no capital and no settlements; its locations stay neutral`);
      continue;
    }

    const placed = placeSettlement(capitalLoc);
    if (placed.cell === null) {
      logWarning("states", `Could not find land for '${specState.name}' capital '${capitalLoc.name}'`);
      continue;
    }

    const stateIndex = pack.states.length;
    const capitalCell = placed.cell;
    let stateCulture = resolveCulture(specState.culture) || pack.cells.culture[capitalCell] || 1;
    if (!pack.cultures[stateCulture]) stateCulture = 1;
    const cultureType = pack.cultures[stateCulture]?.type || "Generic";

    let stateCoa = specState.coa || null;
    if (!stateCoa && typeof window.COA?.generate === "function") {
      stateCoa = window.COA.generate(null, null, null, cultureType);
      stateCoa.shield = window.COA.getShield(stateCulture, null);
    }

    const [x, y] = pack.cells.p[capitalCell];
    const capitalBurgIndex = pack.burgs.length;
    let capitalCoa = capitalLoc.coa || null;
    if (!capitalCoa && typeof window.COA?.generate === "function" && stateCoa) {
      capitalCoa = window.COA.generate(stateCoa, 0.4, null, "Capital");
      capitalCoa.shield = window.COA.getShield(pack.cells.culture[capitalCell] || stateCulture, stateIndex);
    }

    pack.burgs.push({
      i: capitalBurgIndex,
      cell: capitalCell,
      x,
      y,
      state: stateIndex,
      culture: pack.cells.culture[capitalCell] || stateCulture,
      name: capitalLoc.name,
      feature: pack.cells.f[capitalCell],
      capital: 1,
      port: pack.cells.haven?.[capitalCell] ? 1 : 0,
      population: Math.max(defaultPopulation(capitalLoc), 8),
      type: "Capital",
      coa: capitalCoa
    });
    pack.cells.burg[capitalCell] = capitalBurgIndex;
    recordPlacement(placement, capitalLoc, placed, "capital", {state: specState.name, stateIndex});

    const formName = specState.formName || specState.form || "Kingdom";
    const adjForms = ["Empire", "Sultanate", "Khaganate", "Shogunate", "Caliphate", "Despotate", "Tsardom", "Principality"];
    const fullName =
      adjForms.includes(formName) && !/-| /.test(specState.name) ? `${specState.name} ${formName}` : `${formName} of ${specState.name}`;

    pack.states.push({
      i: stateIndex,
      name: specState.name,
      form: specState.form || "Monarchy",
      formName,
      fullName,
      color: specState.color || getRandomColor(),
      capital: capitalBurgIndex,
      center: capitalCell,
      culture: stateCulture,
      type: cultureType,
      removed: false,
      expansionism: specState.expansionism || 1,
      burgs: 1,
      cells: 0,
      area: 0,
      rural: 0,
      urban: 0,
      coa: stateCoa,
      diplomacy: [],
      provinces: [],
      neighbors: [],
      military: []
    });
    pack.cells.state[capitalCell] = stateIndex;
    stateIndexBySpecId.set(specState.id, stateIndex);

    console.log(`[WorldSpecApplicator] Created state ${stateIndex}: ${specState.name} with capital '${capitalLoc.name}' at cell ${capitalCell}`);
  }

  _stateIndexBySpecId = stateIndexBySpecId;
  console.log("[WorldSpecApplicator] Spec states created:", {totalStates: pack.states.length, totalBurgs: pack.burgs.length});
}

let _stateIndexBySpecId = new Map();

/** Owner of a location: its `owner`, else the state whose `locations[]` lists it. */
function ownerOf(loc) {
  if (loc.owner && loc.owner !== "none") return loc.owner;
  const listed = (_specData?.states || []).find(s => Array.isArray(s.locations) && s.locations.includes(loc.id));
  return listed ? listed.id : null;
}

function resolveStateIndex(ownerRef) {
  if (!ownerRef || ownerRef === "none") return 0;
  if (_stateIndexBySpecId.has(ownerRef)) return _stateIndexBySpecId.get(ownerRef);
  const lower = String(ownerRef).toLowerCase();
  for (let i = 1; i < pack.states.length; i++) {
    if (pack.states[i].name.toLowerCase() === lower) return i;
  }
  return 0;
}

function createSpecBurgs(specLocations, placement) {
  console.log("[WorldSpecApplicator] Creating spec burgs and markers from locations...");

  const placedIds = new Set(placement.map(p => p.id));
  let burgsCreated = 0;
  let markersCreated = 0;

  for (const loc of specLocations) {
    if (placedIds.has(loc.id)) continue; // capital already placed

    if (!isSettlementLocation(loc)) {
      if (createSpecMarker(loc, placement)) markersCreated++;
      continue;
    }

    const placed = placeSettlement(loc);
    if (placed.cell === null) {
      logWarning("placement", `Could not find a free land cell for '${loc.name}'`);
      placement.push({id: loc.id, name: loc.name, type: loc.type, as: "unplaced", cell: null});
      continue;
    }

    const cellId = placed.cell;
    const stateId = resolveStateIndex(ownerOf(loc)) || pack.cells.state[cellId] || 0;

    let burgCoa = loc.coa || null;
    if (!burgCoa && typeof window.COA?.generate === "function") {
      const parentCoa = stateId > 0 ? pack.states[stateId]?.coa || null : null;
      burgCoa = window.COA.generate(parentCoa, 0.25, null, loc.type || "City");
      burgCoa.shield = window.COA.getShield(pack.cells.culture[cellId] || 1, stateId);
    }

    const [x, y] = pack.cells.p[cellId];
    const burgIndex = pack.burgs.length;
    pack.burgs.push({
      i: burgIndex,
      cell: cellId,
      x,
      y,
      state: stateId,
      culture: pack.cells.culture[cellId] || 1,
      name: loc.name,
      feature: pack.cells.f[cellId],
      capital: 0,
      port: pack.cells.haven?.[cellId] ? 1 : 0,
      population: defaultPopulation(loc),
      type: loc.type || "City",
      coa: burgCoa
    });
    pack.cells.burg[cellId] = burgIndex;

    // Anchor the owner's territory on this cell so expansion grows from it
    if (stateId > 0) {
      if (!pack.cells.state[cellId]) pack.cells.state[cellId] = stateId;
      pack.states[stateId].burgs = (pack.states[stateId].burgs || 0) + 1;
    }

    if (loc.description) addNote(`burg${burgIndex}`, loc.name, loc.description);
    recordPlacement(placement, loc, placed, "burg", {state: pack.states[stateId]?.name || "Neutrals", stateIndex: stateId});
    burgsCreated++;
  }

  console.log("[WorldSpecApplicator] Spec locations placed:", {burgsCreated, markersCreated, totalBurgs: pack.burgs.length});
}

/**
 * Non-settlement locations become map markers with a legend note. Water
 * features (lakes, rivers) may legitimately sit on water cells.
 */
function createSpecMarker(loc, placement) {
  const type = String(loc.type || "").toLowerCase();
  const allowWater = /lake|river|sea|bay|strait|reef|island|waterfall/.test(type) || String(loc.terrain || "").match(/water|sea|lake/);

  let placed = placeNear(loc.x, loc.y, {requireLand: !allowWater, requireFree: false});
  if (placed.cell === null) placed = placeNear(loc.x, loc.y, {requireLand: false, requireFree: false});
  if (placed.cell === null) {
    logWarning("placement", `Could not place marker '${loc.name}'`);
    return false;
  }

  const style = markerStyleFor(loc);
  const [x, y] = pack.cells.p[placed.cell];
  const marker = {
    type: `spec-${type.replace(/\s+/g, "-") || "landmark"}`,
    icon: style.icon,
    px: style.px,
    x,
    y,
    cell: placed.cell,
    name: loc.name,
    specId: loc.id
  };

  let added;
  if (typeof window.Markers?.add === "function") {
    added = window.Markers.add(marker);
  } else {
    added = {...marker, i: pack.markers.length};
    pack.markers.push(added);
  }

  const ownerState = resolveStateIndex(ownerOf(loc));
  addNote(`marker${added.i}`, loc.name, loc.description || `${loc.type || "Landmark"} mentioned in the source story.`);
  recordPlacement(placement, loc, placed, "marker", {state: pack.states[ownerState]?.name || "Neutrals", stateIndex: ownerState});
  return true;
}

function addNote(id, name, legend) {
  const notesArray = window.notes;
  if (!Array.isArray(notesArray)) return;
  const existing = notesArray.find(n => n.id === id);
  if (existing) {
    existing.name = name;
    existing.legend = legend;
  } else {
    notesArray.push({id, name, legend});
  }
}

function summarizePlacement(placement) {
  const placed = placement.filter(p => p.cell !== null && p.cell !== undefined);
  const exact = placed.filter(p => p.exact).length;
  const maxCells = placed.reduce((m, p) => Math.max(m, p.displacementCells || 0), 0);
  const meanCells = placed.length ? placed.reduce((s, p) => s + (p.displacementCells || 0), 0) / placed.length : 0;
  return {
    total: placement.length,
    placed: placed.length,
    unplaced: placement.length - placed.length,
    burgs: placed.filter(p => p.as === "burg" || p.as === "capital").length,
    markers: placed.filter(p => p.as === "marker").length,
    exact,
    meanDisplacementCells: Math.round(meanCells * 10) / 10,
    maxDisplacementCells: maxCells
  };
}

// ----------------------------------------------------------------------------
// Territory
// ----------------------------------------------------------------------------

function expandStateTerritories(placement) {
  console.log("[WorldSpecApplicator] Expanding state territories from spec locations...");
  const seeded = expandStatesFromSeeds(placement);
  if (!seeded) simpleStateExpansion();

  // Every spec burg must end up inside its owner's territory
  reclaimBurgCells();
  updateStateStatistics();
  calculateStatePoles();
}

/**
 * Territory as a weighted Voronoi diagram seeded by the spec's own locations.
 *
 * FMG's expandStates() grows from capitals using population, biome and culture
 * heuristics (e.g. highlanders pay a 1100 penalty to enter lowlands), which
 * routinely leaves a spec state with a handful of cells and its own towns
 * inside a neighbour. Here every placed location that has an owner is a seed
 * with cost 0 for that owner, and territory spreads outward by travel cost:
 * distance, scaled up by altitude (so borders prefer to run along mountains),
 * by foreign culture, and divided by the state's expansionism. Expansion stops
 * at a reach limit so wilderness stays neutral.
 */
function expandStatesFromSeeds(placement) {
  const {cells, states} = pack;
  const n = cells.i.length;
  const seeds = (placement || []).filter(p => p.cell !== null && p.cell !== undefined && p.stateIndex > 0 && states[p.stateIndex]);
  if (!seeds.length) return false;

  cells.state = new Uint16Array(n);
  const cost = new Float64Array(n).fill(Infinity);
  const queue = new FlatQueue();
  const reachBase = Math.max(graphWidth, graphHeight) * 0.45;

  for (const seed of seeds) {
    if (cost[seed.cell] === 0) continue;
    cost[seed.cell] = 0;
    cells.state[seed.cell] = seed.stateIndex;
    queue.push(seed.cell, 0);
  }

  while (queue.length) {
    const priority = queue.peekValue();
    const current = queue.pop();
    if (priority > cost[current]) continue; // stale entry

    const stateId = cells.state[current];
    const state = states[stateId];
    const expansionism = state.expansionism || 1;
    const reach = reachBase * Math.sqrt(expansionism);
    const [cx, cy] = cells.p[current];

    for (const next of cells.c[current] || []) {
      const h = cells.h[next];
      let factor;
      if (h < SEA_LEVEL) {
        // only near-shore water (so coasts and lakes render inside the state)
        const t = cells.t ? cells.t[next] : -99;
        if (t < -2) continue;
        factor = 2.5;
      } else {
        factor = 1 + Math.max(0, h - 30) / 25; // mountains are hard to cross
      }
      if (cells.culture[next] && cells.culture[next] !== state.culture) factor *= 1.5;

      const [nx, ny] = cells.p[next];
      const total = cost[current] + (Math.hypot(nx - cx, ny - cy) * factor) / expansionism;
      if (total > reach) continue;
      if (total < cost[next]) {
        cost[next] = total;
        cells.state[next] = stateId;
        queue.push(next, total);
      }
    }
  }

  console.log(`[WorldSpecApplicator] Seeded expansion from ${seeds.length} locations`);
  return true;
}

/** Guarantee each burg's own cell belongs to the burg's state. */
function reclaimBurgCells() {
  for (let b = 1; b < pack.burgs.length; b++) {
    const burg = pack.burgs[b];
    if (!burg || burg.removed) continue;
    if (burg.state > 0 && pack.cells.state[burg.cell] !== burg.state) {
      pack.cells.state[burg.cell] = burg.state;
    }
  }
}

function calculateStatePoles() {
  if (typeof window.BurgsAndStates?.getPoles === "function") {
    try {
      window.BurgsAndStates.getPoles();
      return;
    } catch (error) {
      console.warn("[WorldSpecApplicator] getPoles failed:", error);
    }
  }
  for (let s = 1; s < pack.states.length; s++) {
    const state = pack.states[s];
    if (!state.i || state.removed || state.pole) continue;
    state.pole = pack.cells.p[state.center] ? [...pack.cells.p[state.center]] : [0, 0];
  }
}

function simpleStateExpansion() {
  console.log("[WorldSpecApplicator] Running simple state expansion...");
  const cells = pack.cells;
  const stateCenters = [];
  for (let s = 1; s < pack.states.length; s++) {
    const st = pack.states[s];
    if (!st.removed && st.center !== undefined) stateCenters.push({stateId: s, pos: cells.p[st.center]});
  }
  if (!stateCenters.length) return;

  for (let c = 0; c < cells.i.length; c++) {
    if (!isLand(c) || cells.state[c] > 0) continue;
    const [cx, cy] = cells.p[c];
    let nearest = 0;
    let nearestDist = Infinity;
    for (const sc of stateCenters) {
      const d = Math.hypot(cx - sc.pos[0], cy - sc.pos[1]);
      if (d < nearestDist) {
        nearestDist = d;
        nearest = sc.stateId;
      }
    }
    cells.state[c] = nearest;
  }
}

function updateStateStatistics() {
  const {cells, states} = pack;
  if (typeof window.BurgsAndStates?.collectStatistics === "function") {
    try {
      window.BurgsAndStates.collectStatistics(); // cells, area, burgs, rural/urban, neighbors
      for (let s = 1; s < states.length; s++) {
        console.log(`[WorldSpecApplicator] State ${s} (${states[s].name}): ${states[s].cells} cells, ${states[s].burgs} burgs`);
      }
      return;
    } catch (error) {
      console.warn("[WorldSpecApplicator] collectStatistics failed, using fallback:", error);
    }
  }
  for (let s = 1; s < states.length; s++) {
    states[s].cells = 0;
    states[s].area = 0;
  }
  for (let c = 0; c < cells.i.length; c++) {
    const s = cells.state[c];
    if (s > 0 && states[s]) {
      states[s].cells++;
      states[s].area += cells.area?.[c] || 0;
    }
  }
  for (let s = 1; s < states.length; s++) {
    console.log(`[WorldSpecApplicator] State ${s} (${states[s].name}): ${states[s].cells} cells, ${states[s].burgs} burgs`);
  }
}

// ----------------------------------------------------------------------------
// Religions
// ----------------------------------------------------------------------------

function createSpecReligions(specReligions) {
  console.log("[WorldSpecApplicator] Creating", specReligions.length, "religions from spec");
  const resolveCulture = buildCultureLookup();
  const cells = pack.cells;
  cells.religion = new Uint8Array(cells.i.length);

  for (let i = 0; i < specReligions.length; i++) {
    const specReligion = specReligions[i];
    const religionIndex = i + 1;

    let cultureId = resolveCulture(specReligion.culture);
    if (!cultureId) {
      // Spread religions across cultures in order when no culture is given
      const cultureCount = pack.cultures.length - 1;
      cultureId = cultureCount > 0 ? (i % cultureCount) + 1 : 0;
    }

    let centerCell = null;
    if (specReligion.x !== undefined && specReligion.y !== undefined) {
      centerCell = findNearestLandCell(specReligion.x, specReligion.y);
    }
    if (centerCell === null) centerCell = pack.cultures[cultureId]?.center ?? firstLandCell();

    pack.religions.push({
      i: religionIndex,
      name: specReligion.name || `Religion ${religionIndex}`,
      type: specReligion.type || "Organized",
      form: specReligion.form || "Polytheism",
      deity: specReligion.deity || null,
      center: centerCell,
      culture: cultureId,
      color: specReligion.color || getRandomColor(),
      expansion: "culture",
      expansionism: 1,
      removed: false
    });

    // Assign to every land cell of the religion's culture that is not yet taken
    if (cultureId) {
      for (let c = 0; c < cells.i.length; c++) {
        if (cells.culture[c] === cultureId && !cells.religion[c] && isLand(c)) cells.religion[c] = religionIndex;
      }
    }
    if (centerCell !== null) cells.religion[centerCell] = religionIndex;

    console.log(`[WorldSpecApplicator] Created religion ${religionIndex}: ${specReligion.name} (culture ${cultureId})`);
  }
}

// ----------------------------------------------------------------------------
// Roads, burg features, diplomacy, name
// ----------------------------------------------------------------------------

/** Roads and sea routes between the spec's burgs (FMG's own generator). */
function generateRoutes() {
  if (typeof window.Routes?.generate !== "function") return;
  try {
    window.Routes.generate();
    console.log(`[WorldSpecApplicator] Generated ${pack.routes?.length || 0} routes`);
  } catch (error) {
    logApplicatorError("routes", error);
    pack.routes = pack.routes || [];
  }
}

/** Walls, citadel, plaza, temple flags derived from population and capital status. */
function defineBurgFeatures() {
  if (typeof window.BurgsAndStates?.defineBurgFeatures !== "function") return;
  try {
    window.BurgsAndStates.defineBurgFeatures();
  } catch (error) {
    logApplicatorError("burgFeatures", error);
  }
}

/** Diplomacy matrix from explicit relations and the conflict type. */
function applyDiplomacy(spec) {
  try {
    // Only spec states that actually got created are in pack; rebuild the list in pack order
    const created = [];
    for (let s = 1; s < pack.states.length; s++) {
      const specId = [..._stateIndexBySpecId.entries()].find(([, idx]) => idx === s)?.[0];
      const specState = (spec.states || []).find(st => st.id === specId) || {id: specId, name: pack.states[s].name};
      created.push(specState);
    }
    const matrix = buildDiplomacy(created, spec.worldAnalysis, spec.locations || []);
    for (let s = 0; s < pack.states.length; s++) {
      if (pack.states[s]) pack.states[s].diplomacy = matrix[s] || [];
    }
    const enemies = matrix.flat().filter(r => r === "Enemy").length / 2;
    console.log(`[WorldSpecApplicator] Diplomacy set (${enemies} hostile pairs)`);
  } catch (error) {
    logApplicatorError("diplomacy", error);
  }
}

/** Burg type: spec `burgType`, else FMG's terrain-based classification. */
function assignBurgTypes(specLocations) {
  const byName = new Map(specLocations.map(l => [String(l.name).toLowerCase(), l]));
  const getType = window.BurgsAndStates?.getType;
  for (let b = 1; b < pack.burgs.length; b++) {
    const burg = pack.burgs[b];
    if (!burg || burg.removed) continue;
    const loc = byName.get(String(burg.name).toLowerCase());
    const wanted = loc?.burgType && BURG_TYPES.includes(loc.burgType) ? loc.burgType : null;
    try {
      burg.type = wanted || (typeof getType === "function" ? getType(burg.cell, burg.port) : "Generic");
    } catch {
      burg.type = wanted || "Generic";
    }
  }
}

/**
 * Provinces: from `spec.provinces` (seeded growth inside the owning state) when
 * given, otherwise FMG's own generator from the state's burgs.
 */
function generateProvinces(spec) {
  try {
    const specProvinces = Array.isArray(spec.provinces) ? spec.provinces.filter(p => p && p.name) : [];
    if (specProvinces.length) {
      createSpecProvinces(specProvinces);
    } else if (typeof window.Provinces?.generate === "function") {
      window.Provinces.generate();
    } else {
      return;
    }
    if (typeof window.Provinces?.getPoles === "function") window.Provinces.getPoles();
    console.log(`[WorldSpecApplicator] Provinces: ${(pack.provinces?.length || 1) - 1}`);
  } catch (error) {
    logApplicatorError("provinces", error);
    pack.provinces = pack.provinces || [0];
  }
}

function createSpecProvinces(specProvinces) {
  const {cells, states, burgs} = pack;
  const n = cells.i.length;
  cells.province = new Uint16Array(n);
  const provinces = [0];
  const cost = new Float64Array(n).fill(Infinity);
  const queue = new FlatQueue();

  for (const sp of specProvinces) {
    const stateIndex = resolveStateIndex(sp.state);
    if (!stateIndex) {
      logWarning("provinces", `Province '${sp.name}' references unknown state '${sp.state}'`);
      continue;
    }
    const center = sp.center ? placeNear(sp.center.x, sp.center.y, {requireLand: true, requireFree: false, maxRadiusFraction: 0.3}) : {cell: null};
    let cell = center.cell;
    if (cell === null || cells.state[cell] !== stateIndex) {
      // fall back to the state's first cell nearest the requested center
      const candidates = cells.i.filter(i => cells.state[i] === stateIndex && isLand(i));
      if (!candidates.length) continue;
      if (cell === null) cell = candidates[0];
      else {
        const [tx, ty] = cells.p[cell];
        cell = candidates.reduce((best, i) => {
          const d = Math.hypot(cells.p[i][0] - tx, cells.p[i][1] - ty);
          return d < best.d ? {i, d} : best;
        }, {i: candidates[0], d: Infinity}).i;
      }
    }
    const i = provinces.length;
    const burg = cells.burg[cell] || burgs.find(b => b && b.i && b.state === stateIndex)?.i || 0;
    const formName = sp.formName || "Province";
    const state = states[stateIndex];
    let coa = null;
    if (typeof window.COA?.generate === "function") {
      coa = window.COA.generate(state.coa || null, 0.3, null, "Province");
      coa.shield = window.COA.getShield(state.culture, stateIndex);
    }
    provinces.push({
      i,
      state: stateIndex,
      center: cell,
      burg,
      name: sp.name,
      formName,
      fullName: `${sp.name} ${formName}`,
      color: sp.color || getRandomColor(),
      coa
    });
    cells.province[cell] = i;
    cost[cell] = 0;
    queue.push(cell, 0);
  }

  // grow each province inside its own state
  while (queue.length) {
    const priority = queue.peekValue();
    const current = queue.pop();
    if (priority > cost[current]) continue;
    const p = cells.province[current];
    const stateIndex = provinces[p].state;
    const [cx, cy] = cells.p[current];
    for (const next of cells.c[current] || []) {
      if (cells.state[next] !== stateIndex) continue;
      const [nx, ny] = cells.p[next];
      const total = cost[current] + Math.hypot(nx - cx, ny - cy);
      if (total < cost[next]) {
        cost[next] = total;
        cells.province[next] = p;
        queue.push(next, total);
      }
    }
  }

  pack.provinces = provinces;
  for (let s = 1; s < states.length; s++) states[s].provinces = provinces.filter(p => p && p.state === s).map(p => p.i);
}

/** Regiments per state from FMG's military generator (uses diplomacy and area). */
function generateMilitary() {
  if (typeof window.Military?.generate !== "function") return;
  try {
    window.Military.generate();
    const regiments = pack.states.reduce((n, s) => n + (s.military?.length || 0), 0);
    console.log(`[WorldSpecApplicator] Military: ${regiments} regiments`);
  } catch (error) {
    logApplicatorError("military", error);
    for (const s of pack.states) if (s) s.military = s.military || [];
  }
}

/**
 * FMG's random flavour markers (volcanoes, inns, bridges...). Its generate()
 * resets pack.markers, so the spec's own markers are saved and re-added.
 */
function generateFlavourMarkers() {
  if (typeof window.Markers?.generate !== "function") return;
  const notesArray = Array.isArray(window.notes) ? window.notes : null;
  const specMarkers = (pack.markers || []).filter(m => m.specId);
  const specNotes = new Map();
  for (const m of specMarkers) {
    const note = notesArray?.find(n => n.id === `marker${m.i}`);
    if (note) specNotes.set(m.specId, note);
  }
  if (notesArray) {
    const specIds = new Set(specMarkers.map(m => `marker${m.i}`));
    window.notes = notesArray.filter(n => !specIds.has(n.id));
  }

  try {
    window.Markers.generate();
  } catch (error) {
    logApplicatorError("markers", error);
    pack.markers = [];
  }

  // flavour markers must not sit on spec marker cells
  const specCells = new Set(specMarkers.map(m => m.cell));
  pack.markers = pack.markers.filter(m => !specCells.has(m.cell));

  for (const m of specMarkers) {
    const {i, ...rest} = m;
    const added = window.Markers.add(rest);
    const note = specNotes.get(m.specId);
    if (note) addNote(`marker${added.i}`, note.name, note.legend);
  }
  console.log(`[WorldSpecApplicator] Markers: ${specMarkers.length} from spec + ${pack.markers.length - specMarkers.length} flavour`);
}

/** Compare the spec's border hints with the produced territory. */
function checkBorders(spec) {
  if (!Array.isArray(spec.borders) || !spec.borders.length) return null;
  try {
    const report = checkBorderFidelity(
      spec.borders,
      {state: pack.cells.state, c: pack.cells.c, h: pack.cells.h, r: pack.cells.r, biome: pack.cells.biome},
      _stateIndexBySpecId
    );
    for (const b of report.borders) {
      if (!b.passed) logWarning("borders", `border "${b.name}" (${b.type}): ${b.note || `only ${Math.round((b.ratio || 0) * 100)}% along a ${b.type}`}`);
    }
    return report;
  } catch (error) {
    logApplicatorError("borders", error);
    return null;
  }
}

/** Optional visual style preset (spec.map.style). */
async function applyStylePreset(style) {
  if (!style || !STYLE_PRESETS.includes(style)) return;
  if (typeof window.changeStyle !== "function") return;
  try {
    await window.changeStyle(style);
    console.log(`[WorldSpecApplicator] Style preset: ${style}`);
  } catch (error) {
    logWarning("style", `Could not apply style '${style}': ${error.message}`);
  }
}

/** Map name from the spec, locked so later regenerations keep it. */
function applyMapName(spec) {
  const name = mapNameFromSpec(spec);
  if (!name) return;
  const input = document.getElementById("mapName");
  if (input) input.value = name;
  if (typeof window.lock === "function") window.lock("mapName");
  console.log(`[WorldSpecApplicator] Map name: ${name}`);
}

// ----------------------------------------------------------------------------
// Rendering helpers
// ----------------------------------------------------------------------------

function redrawMapLayers() {
  try {
    ensureCoasExist();
    ensureLayerOn("toggleMarkers", pack.markers?.length > 0);
    ensureLayerOn("toggleZones", pack.zones?.length > 0);
    ensureLayerOn("toggleBurgs", true);
    ensureLayerOn("toggleLabels", true);
    ensureLayerOn("toggleStates", true);
    ensureLayerOn("toggleBorders", true);
    if (typeof window.drawLayers === "function") {
      window.drawLayers();
    } else {
      for (const fn of ["drawStateLabels", "drawStates", "drawBorders", "drawBurgIcons", "drawBurgLabels", "drawMarkers"]) {
        if (typeof window[fn] === "function") window[fn]();
      }
    }
    if (typeof window.COArenderer?.drawAll === "function") window.COArenderer.drawAll();
    console.log("[WorldSpecApplicator] Map layers redrawn");
  } catch (error) {
    logApplicatorError("redrawMapLayers", error);
  }
}

/** Turn a layer on (without toggling it off if it is already on). */
function ensureLayerOn(buttonId, wanted) {
  if (!wanted) return;
  try {
    if (typeof window.layerIsOn !== "function" || window.layerIsOn(buttonId)) return;
    if (typeof window.turnButtonOn === "function") window.turnButtonOn(buttonId);
  } catch (error) {
    console.warn(`[WorldSpecApplicator] Could not enable layer ${buttonId}:`, error);
  }
}

function ensureCoasExist() {
  const hasCOA = typeof window.COA?.generate === "function";
  if (!hasCOA) return;

  for (let s = 1; s < pack.states.length; s++) {
    const state = pack.states[s];
    if (state.removed || state.coa) continue;
    const cultureType = pack.cultures[state.culture]?.type || "Generic";
    state.coa = window.COA.generate(null, null, null, cultureType);
    state.coa.shield = window.COA.getShield(state.culture, null);
  }

  for (let b = 1; b < pack.burgs.length; b++) {
    const burg = pack.burgs[b];
    if (!burg || burg.removed || burg.coa) continue;
    const state = burg.state > 0 ? pack.states[burg.state] : null;
    const type = burg.capital ? "Capital" : burg.type || "City";
    burg.coa = window.COA.generate(state?.coa || null, burg.capital ? 0.4 : 0.25, null, type);
    burg.coa.shield = window.COA.getShield(burg.culture || 1, burg.state || 0);
  }
}

// ----------------------------------------------------------------------------
// Zones
// ----------------------------------------------------------------------------

function applyZones(specZones) {
  if (!pack.zones) pack.zones = [];

  const zoneColors = {
    disaster: "url(#hatch5)",
    invasion: "url(#hatch1)",
    rebels: "url(#hatch3)",
    disease: "url(#hatch12)",
    eruption: "url(#hatch7)",
    flood: "url(#hatch13)"
  };

  for (const zone of specZones) {
    if (!zone.center) continue;
    const {x, y} = normalizedToMapCoords(zone.center.x, zone.center.y);
    const radiusPixels = (zone.radius || 0.05) * Math.max(graphWidth, graphHeight);
    const cellsInZone = findAll(x, y, radiusPixels).filter(c => isLand(c));
    if (cellsInZone.length === 0) {
      logWarning("zones", `Zone '${zone.name}' has no land cells`);
      continue;
    }
    pack.zones.push({
      i: pack.zones.length,
      name: zone.name,
      type: zone.type,
      cells: cellsInZone,
      color: zoneColors[String(zone.type || "").toLowerCase()] || "url(#hatch5)",
      description: zone.description || ""
    });
  }
}

// ============================================================================
// Spec cleanup
// ============================================================================

function cleanupWorldSpec(spec) {
  if (spec.states && spec.locations) {
    for (const state of spec.states) {
      if (state.locations) {
        state.locations = state.locations.filter(locId => {
          const loc = spec.locations.find(l => l.id === locId);
          return loc && loc.owner === state.id;
        });
      }
    }
  }

  if (spec.terrain?.heightmapCommands) {
    spec.terrain.heightmapCommands = spec.terrain.heightmapCommands.map(cmd =>
      typeof cmd === "string" ? cmd.split("#")[0].trim() : cmd
    );
  }

  // Drop border hints that cannot be checked (need two state ids)
  if (Array.isArray(spec.borders)) {
    spec.borders = spec.borders.filter(b => b && Array.isArray(b.between) && b.between.length >= 2);
  }

  // Clamp any out-of-range normalized coordinates instead of failing later
  const clamp = v => (typeof v === "number" ? Math.min(1, Math.max(0, v)) : v);
  for (const loc of spec.locations || []) {
    loc.x = clamp(loc.x);
    loc.y = clamp(loc.y);
  }
  for (const f of spec.terrain?.features || []) {
    if (Array.isArray(f.points)) f.points = f.points.map(p => (Array.isArray(p) ? [clamp(p[0]), clamp(p[1])] : p));
  }

  return spec;
}

// ============================================================================
// Exports
// ============================================================================

export const WorldSpecApplicator = {
  generateFromSpec,
  validateSpec,
  normalizedToMapCoords,
  findNearestCell,
  findNearestLandCell,
  findSuitableBurgCell,
  placeNear,
  isSettlementLocation,
  seedFromSpec,
  getErrors,
  getWarnings,
  cleanupWorldSpec,
  clearErrors,
  getConflictSummary: spec => {
    try {
      return getConflictSummary(spec);
    } catch {
      return null;
    }
  }
};

if (typeof window !== "undefined") {
  window.WorldSpecApplicator = WorldSpecApplicator;
}
